struct TrieNode {
    TrieNode* child[2] = {};
    int count = 0;
};

class Solution {
    TrieNode* root = new TrieNode();

    void insert(int num) {
        TrieNode* node = root;
        for (int i = 14; i >= 0; --i) {
            int bit = (num >> i) & 1;
            if (!node->child[bit]) node->child[bit] = new TrieNode();
            node = node->child[bit];
            node->count++;
        }
    }

    int countLess(int num, int limit) {
        TrieNode* node = root;
        int res = 0;
        for (int i = 14; i >= 0 && node; --i) {
            int nBit = (num >> i) & 1;
            int lBit = (limit >> i) & 1;
            if (lBit == 1) {
                if (node->child[nBit]) res += node->child[nBit]->count;
                node = node->child[1 - nBit];
            } else {
                node = node->child[nBit];
            }
        }
        return res;
    }

public:
    int countPairs(vector<int>& nums, int low, int high) {
        int res = 0;
        for (int num : nums) {
            res += countLess(num, high + 1) - countLess(num, low);
            insert(num);
        }
        return res;
    }
};
